import json,math,random,re,sys,unicodedata,csv,difflib
R='C:/verger-data/pilot/registry/'
STOP=set('le la les l the and et de du des d a an of restaurant cafe bar bistro brasserie pub coffee shop'.split())
def norm(s):
    s=unicodedata.normalize('NFKD',s.lower());s=''.join(c for c in s if not unicodedata.combining(c))
    s=re.sub(r'[^a-z0-9]+',' ',s)
    return [t for t in s.split() if t not in STOP]
def teq(a,b): return a==b or difflib.SequenceMatcher(None,a,b).ratio()>=0.85
def score(A,B):
    if not A or not B: return 0.0
    s,l=(A,B) if len(A)<=len(B) else (B,A)
    return sum(1 for t in s if any(teq(t,u) for u in l))/len(s)
def dist(a,b,c,d):
    x=math.radians(c-a);y=math.radians(d-b)*math.cos(math.radians((a+c)/2))
    return 6371000*math.hypot(x,y)
def best(place,cands,open_key):
    # cands: list of (names, lat, lng, is_open, ref)
    A=norm(place['name']);hits=[]
    for names,la,lo,op,ref in cands:
        if la is None: continue
        d=dist(place['lat'],place['lng'],la,lo)
        if d>100: continue
        sc=max((score(A,norm(n)) for n in names if n),default=0)
        if sc>=0.5: hits.append((sc,-d,op,ref,names[0] if names else ''))
    if not hits: return None
    hits.sort(key=lambda h:(h[0],h[1]),reverse=True)
    b=hits[0]
    anyopen=any(h[2] for h in hits)
    return {'score':round(b[0],3),'dist':round(-b[1],1),'best_open':b[2],'any_open':anyopen,'ref':b[3],'rname':b[4],'n_hits':len(hits)}
def fr_cands(rec):
    out={}
    for r in rec['res']:
        for u in r.get('results',[]):
            unames=[u.get('nom_complet'),u.get('nom_raison_sociale'),u.get('sigle')]
            es=list(u.get('matching_etablissements') or [])
            if u.get('siege'): es.append(u['siege'])
            for e in es:
                try: la,lo=float(e['latitude']),float(e['longitude'])
                except Exception: continue
                sid=e.get('siret')
                en=[e.get('nom_commercial'),e.get('denomination_usuelle_1')]+list(e.get('liste_enseignes') or [])
                out[sid]=(unames+en,la,lo,e.get('etat_administratif')=='A',sid)
    return list(out.values())
def load_fr():
    return {json.loads(l)['venueId']:fr_cands(json.loads(l)) for l in open(R+'fr_raw.jsonl',encoding='utf8')}
def load_sla():
    out=[]
    for fn,op in(('sla_9s3h-dpkz.csv',True),('sla_6dg3-2z7i.csv',False)):
        for i,row in enumerate(csv.DictReader(open(R+fn,encoding='utf8',newline=''))):
            if row['Premises County'] not in('Bronx','Kings','New York','Queens','Richmond'): continue
            m=re.search(r'POINT \((-?[\d.]+) (-?[\d.]+)\)',row.get('Georeference') or '')
            if not m: continue
            out.append(([row['DBA'],row['LegalName']],float(m.group(2)),float(m.group(1)),op,'%s:%d:%s'%(fn,i+2,row['License Permit ID'])))
    return out
def load_uk():
    out={}
    for l in open(R+'uk_raw.jsonl',encoding='utf8'):
        d=json.loads(l);c=[]
        for e in d['res'].get('establishments',[]):
            try: c.append(([e['BusinessName']],float(e['geocode']['latitude']),float(e['geocode']['longitude']),True,str(e['FHRSID'])))
            except Exception: pass
        out[d['venueId']]=c
    return out
def wilson(k,n,z=1.96):
    if n==0: return (0,0)
    p=k/n;den=1+z*z/n;c=(p+z*z/2/n)/den;h=z*math.sqrt(p*(1-p)/n+z*z/4/n/n)/den
    return (c-h,c+h)
def main():
    res={}
    smp={c:json.load(open(R+'sample_%s.json'%c,encoding='utf8')) for c in('Paris','New_York','London')}
    fr=load_fr();sla=load_sla();uk=load_uk()
    for c,s in smp.items():
        rows=[]
        for p in s:
            cands=fr.get(p['venueId'],[]) if c=='Paris' else uk.get(p['venueId'],[]) if c=='London' else None
            if c=='New_York':
                # prefilter by bbox for speed
                cands=[x for x in sla if abs(x[1]-p['lat'])<0.0015 and abs(x[2]-p['lng'])<0.0025]
            b=best(p,cands,None)
            rows.append({'venueId':p['venueId'],'name':p['name'],'lat':p['lat'],'lng':p['lng'],'match':b})
        res[c]=rows
        json.dump(rows,open(R+'match_%s.json'%c,'w',encoding='utf8'),ensure_ascii=False,indent=0)
    summ={}
    tot_k=tot_n=0;tot_k2=0
    for c,rows in res.items():
        m=[r for r in rows if r['match']]
        # closed: best closed and no open hit (conservative); sens: best closed
        cl=[r for r in m if not r['match']['any_open']]
        cl2=[r for r in m if not r['match']['best_open']]
        summ[c]={'n':len(rows),'matched':len(m),'cov':len(m)/len(rows),'cov_wilson':wilson(len(m),len(rows))}
        if c!='London':
            summ[c].update({'closed':len(cl),'closed_sens':len(cl2),'closed_share':len(cl)/len(m) if m else None,'closed_wilson':wilson(len(cl),len(m))})
            tot_k+=len(cl);tot_n+=len(m);tot_k2+=len(cl2)
        # manual check sample
